<?php require_once __DIR__.'/config/database.php'; require_once __DIR__.'/includes/functions.php';
if (!empty($_SESSION['user_id'])) redirect('dashboard.php'); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){ csrf_check(); $username=trim($_POST['username']??''); $password=$_POST['password']??''; $st=$pdo->prepare('SELECT id,username,password_hash,full_name FROM users WHERE username=? AND is_active=1 LIMIT 1'); $st->execute([$username]); $u=$st->fetch(); if($u && password_verify($password,$u['password_hash'])) { session_regenerate_id(true); $_SESSION['user_id']=(int)$u['id']; $_SESSION['username']=$u['username']; $_SESSION['name']=$u['full_name']; unset($_SESSION['csrf_token']); csrf_token(); redirect('dashboard.php'); } $error='Invalid username or password.'; }
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Login | Shop Inventory</title><link rel="stylesheet" href="assets/css/style.css"></head><body class="login-body"><div class="login-card"><div class="login-brand"><span class="brand-icon">▦</span><div><h1>Shop Inventory</h1><p>Management Console</p></div></div><div class="login-heading"><h2>Welcome back</h2><p>Sign in to manage your shop.</p></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif; ?><?php $f=get_flash(); if($f):?><div class="alert <?=e($f['type'])?>"><?=e($f['message'])?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Username<input name="username" required autocomplete="username" autofocus></label><label>Password<input type="password" name="password" required autocomplete="current-password"></label><button class="btn primary full" type="submit">Sign in →</button></form><p class="login-note">Secure administrator access · XAMPP local application</p></div></body></html>
